using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
using LivingLosSantosV2;
internal static class WorldPolicyTests
{
    private static void Assert(bool value) { if(!value) throw new Exception("World policy assertion failed."); }
    private static void Reject(Action action) { bool rejected=false; try {action();} catch {rejected=true;} Assert(rejected); }
    private static Dictionary<string,object> Command(DateTime now)
    { return new Dictionary<string,object>{{"id","command-1"},{"runtimeId","session-1"},{"status","queued"},{"createdAt",now.ToString("o")},{"expiresAt",now.AddSeconds(30).ToString("o")}}; }
    public static void Run(Action<string,Action> check)
    {
        check("director frequent defaults exact",delegate {var s=new DirectorSettings(); Assert(s.enabled&&s.turfWars&&s.streetFights&&s.ambientHostility==65&&s.gangAggression==75&&s.civilianPanic==70&&s.eventIntervalSeconds==75&&s.maxActiveEvents==2&&s.maxSpawnedPeds==16);});
        check("settings invalid scalar never coerced",delegate {var m=new DirectorSettings().Snapshot(); m["enabled"]="false"; Reject(delegate{DirectorSettings.Parse(m);}); m=new DirectorSettings().Snapshot(); m["gangAggression"]=Double.NaN; Reject(delegate{DirectorSettings.Parse(m);}); m["gangAggression"]=15.2; Reject(delegate{DirectorSettings.Parse(m);});});
        check("settings reject missing field and spawn overflow",delegate {var m=new DirectorSettings().Snapshot(); m.Remove("blips"); Reject(delegate{DirectorSettings.Parse(m);}); m=new DirectorSettings().Snapshot(); m["maxSpawnedPeds"]=25; Reject(delegate{DirectorSettings.Parse(m);});});
        check("settings boundaries accepted",delegate {var m=new DirectorSettings().Snapshot(); m["eventIntervalSeconds"]=30; m["maxSpawnedPeds"]=4; m["gangAggression"]=0; Assert(DirectorSettings.Parse(m).maxSpawnedPeds==4); m["eventIntervalSeconds"]=300; m["maxSpawnedPeds"]=24; m["gangAggression"]=100; Assert(DirectorSettings.Parse(m).gangAggression==100);});
        check("settings snapshot preserves boolean false",delegate {var s=new DirectorSettings{enabled=false,blips=false,subtitles=false}; var restored=DirectorSettings.Parse(s.Snapshot()); Assert(!restored.enabled&&!restored.blips&&!restored.subtitles);});
        check("command is executed only once",delegate {var gate=new CommandGate(); var now=DateTime.UtcNow; var c=Command(now); string error; Assert(gate.TryClaim(c,"session-1",now,out error)); Assert(!gate.TryClaim(c,"session-1",now.AddSeconds(1),out error)&&error==null);});
        check("old-session command rejected without claiming new session",delegate {var gate=new CommandGate(); var now=DateTime.UtcNow; string error; Assert(!gate.TryClaim(Command(now),"session-2",now,out error)&&error!=null); Assert(gate.TryClaim(Command(now),"session-1",now,out error));});
        check("expired command never dispatched",delegate {var now=DateTime.UtcNow; string error; Assert(!new CommandGate().TryClaim(Command(now.AddSeconds(-31)),"session-1",now,out error)&&error!=null);});
        check("future and unbounded command TTL rejected",delegate {var now=DateTime.UtcNow; string error; var c=Command(now.AddMinutes(1)); Assert(!new CommandGate().TryClaim(c,"session-1",now,out error)); c=Command(now); c["expiresAt"]=now.AddMinutes(2).ToString("o"); Assert(!new CommandGate().TryClaim(c,"session-1",now,out error));});
        check("applied commands are not replayed",delegate {var now=DateTime.UtcNow; string error; var c=Command(now); c["status"]="applied"; Assert(!new CommandGate().TryClaim(c,"session-1",now,out error));});
        check("malformed command fields rejected",delegate {var now=DateTime.UtcNow; var c=Command(now); c["expiresAt"]="not-date"; Reject(delegate{string error; new CommandGate().TryClaim(c,"session-1",now,out error);});});
        check("winner requires actual sole surviving side",delegate {Assert(WorldRules.Winner(2,0,true,false)=="attacker"); Assert(WorldRules.Winner(0,3,true,false)=="defender"); Assert(WorldRules.Winner(2,3,true,false)==null); Assert(WorldRules.Winner(0,0,true,false)==null);});
        check("timeouts and missing participants never transfer turf",delegate {Assert(WorldRules.Winner(3,0,false,false)==null); Assert(WorldRules.Winner(3,0,true,true)==null); Assert(WorldRules.Winner(-1,1,true,false)==null);});
        check("owned handle model and existence all required",delegate {Assert(WorldRules.CanOwn(1,1,10,10,true)); Assert(!WorldRules.CanOwn(1,2,10,10,true)); Assert(!WorldRules.CanOwn(1,1,10,11,true)); Assert(!WorldRules.CanOwn(1,1,10,10,false));});
        check("safe spawn needs ground clearance and proximity",delegate {Assert(WorldRules.SafePlacement(30,4,0.1,true,true)); Assert(!WorldRules.SafePlacement(3,4,0,true,true)); Assert(!WorldRules.SafePlacement(30,4,0,false,true)); Assert(!WorldRules.SafePlacement(30,4,0,true,false)); Assert(!WorldRules.SafePlacement(30,4,9,true,true)); Assert(!WorldRules.SafePlacement(150,4,0,true,true));});
        check("nonfinite and negative placement values rejected",delegate {Assert(!WorldRules.SafePlacement(Double.NaN,4,0,true,true)); Assert(!WorldRules.SafePlacement(30,Double.NegativeInfinity,0,true,true)); Assert(!WorldRules.SafePlacement(30,-1,0,true,true)); Assert(!WorldRules.SafePlacement(30,4,Double.NaN,true,true));});
        check("placement covers distinct bounded radial candidates",delegate {var points=Enumerable.Range(0,WorldRules.PlacementCandidates).Select(i=>WorldRules.PlacementOffset(0,4,i,0)).ToArray(); Assert(points.Length==48&&WorldRules.PlacementCandidatesPerPulse==8); foreach(var p in points) {double r=Math.Sqrt(p.Item1*p.Item1+p.Item2*p.Item2); Assert(r>=17.99&&r<=43.01&&!Single.IsNaN(p.Item1)&&!Single.IsNaN(p.Item2));} Assert(points.Select(p=>Math.Round(p.Item1)+":"+Math.Round(p.Item2)).Distinct().Count()>=40);});
        check("placement first fan separates opponents and teammates",delegate {var a=WorldRules.PlacementOffset(0,4,0,0); var b=WorldRules.PlacementOffset(4,4,0,0); Assert(Math.Abs(a.Item1+b.Item1)<0.001&&Math.Abs(a.Item2+b.Item2)<0.001); var mate=WorldRules.PlacementOffset(1,4,0,0); Assert(Math.Sqrt(Math.Pow(a.Item1-mate.Item1,2)+Math.Pow(a.Item2-mate.Item2,2))>10);});
        check("placement fallback explores all four quadrants",delegate {var points=Enumerable.Range(24,24).Select(i=>WorldRules.PlacementOffset(0,4,i,0)).ToArray(); Assert(points.Any(p=>p.Item1>5&&p.Item2>5)&&points.Any(p=>p.Item1< -5&&p.Item2>5)&&points.Any(p=>p.Item1< -5&&p.Item2< -5)&&points.Any(p=>p.Item1>5&&p.Item2< -5));});
        check("witness placement has distinct origin and all crew sizes valid",delegate {for(int team=1;team<=4;team++) {var witness=WorldRules.PlacementOffset(team*2,team,0,0); var defender=WorldRules.PlacementOffset(team,team,0,0); Assert(Math.Sqrt(Math.Pow(witness.Item1-defender.Item1,2)+Math.Pow(witness.Item2-defender.Item2,2))>10); for(int i=0;i<=team*2;i++) WorldRules.PlacementOffset(i,team,47,Math.PI/3);}});
        check("placement rejects invalid index budget and phase",delegate {Reject(delegate{WorldRules.PlacementOffset(0,0,0,0);}); Reject(delegate{WorldRules.PlacementOffset(9,4,0,0);}); Reject(delegate{WorldRules.PlacementOffset(0,4,48,0);}); Reject(delegate{WorldRules.PlacementOffset(0,4,0,Double.NaN);});});
        check("six canonical districts and initial ownership",delegate {var t=WorldRules.Territories(); Assert(t.Length==6&&t.Select(x=>x.id).Distinct().Count()==6); Assert(t.Single(x=>x.id=="grove").owner=="Ballas"); Assert(t.Single(x=>x.id=="rancho").x==480);});
        check("campaign persists observed owner wins and settings",delegate {WithStore(delegate(CampaignStore store,string path) {var t=WorldRules.Territories(); t[0].owner="Families"; t[0].wins=7; t[0].heat=45; t[0].challenger="Vagos"; store.Save(store.Serialize(t,new DirectorSettings{enabled=false})); var restored=WorldRules.Territories(); var settings=store.Load(restored); Assert(restored[0].owner=="Families"&&restored[0].wins==7&&restored[0].heat==45&&restored[0].challenger==null&&!settings.enabled);});});
        check("invalid campaign cannot partially mutate territories",delegate {WithStore(delegate(CampaignStore store,string path) {var t=WorldRules.Territories(); t[0].owner="Families"; t[5].owner="Bogus"; File.WriteAllText(path,store.Serialize(t,new DirectorSettings())); var target=WorldRules.Territories(); Reject(delegate{store.Load(target);}); Assert(target[0].owner=="Ballas");});});
        check("campaign validates duplicates and bounds",delegate {WithStore(delegate(CampaignStore store,string path) {var t=WorldRules.Territories(); t[1].id=t[0].id; File.WriteAllText(path,store.Serialize(t,new DirectorSettings())); Reject(delegate{store.Load(WorldRules.Territories());}); t=WorldRules.Territories(); t[0].wins=-1; File.WriteAllText(path,store.Serialize(t,new DirectorSettings())); Reject(delegate{store.Load(WorldRules.Territories());});});});
        check("atomic campaign replacement retains previous backup",delegate {WithStore(delegate(CampaignStore store,string path) {var t=WorldRules.Territories(); store.Save(store.Serialize(t,new DirectorSettings())); t[0].owner="Vagos"; store.Save(store.Serialize(t,new DirectorSettings())); Assert(File.Exists(path+".bak")&&File.ReadAllText(path+".bak").Contains("Ballas")&&!File.Exists(path+".tmp"));});});
        check("rejected campaign gets dated preserved copy",delegate {WithStore(delegate(CampaignStore store,string path) {File.WriteAllText(path,"broken campaign"); string saved=store.PreserveRejected(); store.Save(store.Serialize(WorldRules.Territories(),new DirectorSettings())); Assert(File.ReadAllText(saved)=="broken campaign");});});
    }
    private static void WithStore(Action<CampaignStore,string> action)
    { string folder=Path.Combine(Path.GetTempPath(),"lls-world-tests-"+Guid.NewGuid().ToString("N")); Directory.CreateDirectory(folder); try {string path=Path.Combine(folder,"campaign.json"); action(new CampaignStore(path),path);} finally {Directory.Delete(folder,true);} }
}
